"""Generate SPYDER informational product microsites from a single local template.
This script is for maintainers only; the site remains deployable as static files.
"""
from pathlib import Path
from html import escape
S = Path(__file__).resolve().parents[1]/'site'

def T(en, ru, tag='span', klass='', extra=''):
    return f'<{tag} data-en="{escape(en,quote=True)}" data-ru="{escape(ru,quote=True)}"{(" class="+chr(34)+klass+chr(34)) if klass else ""} {extra}>{escape(en)}</{tag}>'

def header():
 return '''<header class="site-nav" id="top"><div class="container nav-inner">
<a class="brand" href="/"><span class="brand-mark"><img src="/assets/spyder-symbol-white.png" alt="" width="27" height="30"></span> SPYDER</a>
<nav class="nav-links" aria-label="Primary navigation"><a href="/wallet.html" data-en="Wallet" data-ru="Кошелёк">Wallet</a><a href="/network.html">Network</a><a href="/chain.html">Chain</a><a href="/security.html" data-en="Security" data-ru="Безопасность">Security</a><a href="/support.html" data-en="Support" data-ru="Помощь">Support</a><a href="/#ecosystem" data-en="Ecosystem" data-ru="Экосистема">Ecosystem</a></nav>
<div class="nav-actions"><button class="lang active" data-lang="en" aria-pressed="true" type="button">EN</button><span class="lang-sep">/</span><button class="lang" data-lang="ru" aria-pressed="false" type="button">RU</button><a class="pill pill-white desktop-cta" href="/download.html" data-en="Get the app" data-ru="Приложение">Get the app</a><button class="hamburger" id="mobile-toggle" type="button" aria-label="Open menu" aria-controls="mobile-menu" aria-expanded="false"><svg fill="none" height="25" stroke="currentColor" stroke-width="1.8" viewBox="0 0 24 24" width="25"><path d="M3 7h18M3 17h18"/></svg></button></div></div></header>
<nav class="mobile-menu" id="mobile-menu" aria-label="Mobile navigation"><a href="/" data-en="Home" data-ru="Главная">Home</a><a href="/wallet.html" data-en="Wallet" data-ru="Кошелёк">Wallet</a><a href="/network.html">Network</a><a href="/chain.html">Chain</a><a href="/security.html" data-en="Security" data-ru="Безопасность">Security</a><a href="/support.html" data-en="Support" data-ru="Помощь">Support</a><a href="/#ecosystem" data-en="Ecosystem" data-ru="Экосистема">Ecosystem</a></nav>'''

def footer():
 return '''<footer class="sub-footer"><div class="container"><div class="footer-top"><div><a class="brand" href="/"><span class="brand-mark"><img src="/assets/spyder-symbol-white.png" alt="" width="27" height="30"></span> SPYDER</a><p class="footer-sub" data-en="The connected SPYDER product ecosystem. Features are released in stages." data-ru="Экосистема продуктов SPYDER. Возможности выпускаются поэтапно.">The connected SPYDER product ecosystem. Features are released in stages.</p></div><div class="footer-links"><div><b data-en="PRODUCTS" data-ru="ПРОДУКТЫ">PRODUCTS</b><a href="/wallet.html">Wallet</a><a href="/network.html">Network</a><a href="/chain.html">Chain & SPD</a></div><div><b data-en="RESOURCES" data-ru="ИНФОРМАЦИЯ">RESOURCES</b><a href="/security.html" data-en="Security" data-ru="Безопасность">Security</a><a href="/download.html" data-en="Availability" data-ru="Доступность">Availability</a><a href="/support.html" data-en="Support" data-ru="Поддержка">Support</a><a href="/#roadmap">Roadmap</a><a href="/#faq">FAQ</a></div><div><b data-en="LEGAL" data-ru="ДОКУМЕНТЫ">LEGAL</b><a href="/privacy.html" data-en="Privacy" data-ru="Конфиденциальность">Privacy</a><a href="/terms.html" data-en="Terms" data-ru="Условия">Terms</a></div></div></div><div class="footer-bottom"><span>© <span id="year">2026</span> SPYDER</span><span data-en="Never share your recovery phrase or private keys." data-ru="Никому не сообщайте seed-фразу и приватные ключи.">Never share your recovery phrase or private keys.</span></div></div></footer>'''

def card(no,heading,heading_ru,desc,desc_ru):
 return f'<article class="detail-card reveal"><span class="detail-card-index">{no}</span>{T(heading,heading_ru,"h3")}{T(desc,desc_ru,"p")}</article>'

def section(kicker,kr,title,tr,body,br,cards):
 return f'<section class="detail-section section-light section"><div class="container"><div class="detail-section-heading"><div>{T(kicker,kr,"div","kicker")}{T(title,tr,"h2","section-h2")}</div>{T(body,br,"p","section-description")}</div><div class="detail-card-grid">{cards}</div></div></section>'

def make(name, en_title, ru_title, eyebrow, eyebrow_ru, headline, headline_ru, intro, intro_ru, status, status_ru, visual, inner, cta_en, cta_ru, cta_href='/#get-app'):
 title_en = f'{en_title} — SPYDER';title_ru = f'{ru_title} — SPYDER'
 html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#09090b"><meta name="description" content="{escape(intro[:155],quote=True)}"><meta name="color-scheme" content="dark light"><title>{escape(title_en)}</title><link rel="canonical" href="https://spyder.ac/{name}.html"><link rel="stylesheet" href="/assets/styles.css"><link rel="icon" href="/assets/favicon-48.png"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title_en,quote=True)}"><meta property="og:description" content="{escape(intro[:155],quote=True)}"><meta property="og:image" content="https://spyder.ac/assets/og-spyder.png"><meta name="twitter:card" content="summary_large_image"></head>
<body data-title-en="{escape(title_en,quote=True)}" data-title-ru="{escape(title_ru,quote=True)}"><div class="scroll-progress" id="scroll-progress" aria-hidden="true"></div>{header()}
<main><section class="sub-hero section"><div class="container sub-hero-grid"><div class="sub-hero-copy">{T(eyebrow,eyebrow_ru,'div','kicker subdued')} {T(headline,headline_ru,'h1','sub-title')} {T(intro,intro_ru,'p','sub-description')}<div class="sub-actions"><a class="pill pill-white" href="{cta_href}">{T(cta_en,cta_ru)} <span aria-hidden="true">↗</span></a><a class="pill pill-outline" href="/">{T('Back to SPYDER','На главную')} <span aria-hidden="true">→</span></a></div><p class="sub-status">{T(status,status_ru)}</p></div><div class="sub-visual" aria-hidden="true">{visual}</div></div></section>{inner}
<section class="sub-closing section"><div class="container sub-closing-inner">{T('The future is built in stages.','Будущее создаётся поэтапно.','h2','section-h2')}{T('Explore what exists today and follow the roadmap for what comes next.','Узнайте, что уже разрабатывается, и следите за следующими этапами.','p')}<a href="/#roadmap" class="pill pill-white">{T('Explore roadmap','Посмотреть roadmap')} <span aria-hidden="true">↗</span></a></div></section></main>{footer()}<script defer src="/assets/app.js"></script></body></html>'''
 (S/f'{name}.html').write_text(html,encoding='utf-8')

